from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.6, 'crossover': 0.85, 'exploration': 0.45, 'local_fraction': 0.35, 'radius': 0.15, 'population': 30, 'generations': 6, 'reason': 'With only 24 of 100 evaluations used and 20 stagnant steps with zero recent improvement, the search needs more exploration to escape a flat/plateau region. auto lets held-out RMSE pick RBF vs quadratic given sparse 5-D data; current_to_best balances convergence with diversity. Moderate mutation (0.6) and high crossover (0.85) for recombination, elevated exploration (0.45) to reward novelty distance, and local_fraction 0.35/radius 0.15 for a light local refinement without over-exploiting a possibly misleading surrogate. Population 30 and 6 generations keep surrogate re-fits and true-evaluation batches economical within the fixed budget.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
